  'dash.settings.api_key_saved_placeholder': '•••••••• (gespeichert — erneut eingeben zum Ändern)',
  'dash.settings.autonomous_confirm': 'Zum Autonomem Modus wechseln?\n\nDies genehmigt automatisch jede Werkzeugkategorie — bash, git, file_write, file_edit, database_query, browser, http_request — einschließlich ihrer destruktiven Teilmenge (rm, format, deletes, overwrites). Die einzigen Vorgänge, die noch eine Bestätigung erfordern, sind irreversible Muster (force-push, hard reset, history rewrites, package publish, git_commit --amend) — diese werden niemals freigegeben.\n\nWähle dies nur, wenn du möchtest, dass Ava ohne Bestätigungen über lange Sitzungen hinweg läuft, und nur in einem Arbeitsbereich, von dem du einen falschen Schreibvorgang über git wiederherstellen kannst.',
  'dash.settings.avatar': 'Avatar',
  'dash.settings.avatar_hint': 'Lokal gespeichert. Von der Synchronisierungsseite mit der Cloud synchronisieren. JPEG, PNG, WebP oder GIF. Max. 2 MB.',
  'dash.settings.base_url': 'Basis-URL',
  'dash.settings.change_avatar': 'Avatar ändern',
  'dash.settings.configured': 'Konfiguriert',
  'dash.settings.custom_banner': 'Benutzerdefiniert — du hast einzelne Kategorien angepasst. Wähle oben eine Voreinstellung, um zurückzusetzen.',
  'dash.settings.custom_model': 'Benutzerdefiniertes Modell',
  'dash.settings.custom_model_desc': 'Richte Ava auf jedes Modell ein — lokal (Ollama, LM Studio, vLLM auf deinem Gerät) oder remote (privates vLLM-Cluster, selbst gehostetes Finetuning, OpenRouter, Together, alles, das die OpenAI Chat Completions API spricht). Lokale Server bleiben auf deinem Gerät; Remote-Endpunkte erhalten die Sicherheit, die dein Endpunkt bietet. Starte das Chat-Fenster nach dem Speichern neu, damit Änderungen wirksam werden.',
  'dash.settings.custom_model_title': 'Benutzerdefiniertes Modell — Ollama, LM Studio, vLLM oder ein beliebiges OpenAI-kompatibles Endpunkt',
  'dash.settings.customise_by_category': 'Nach Kategorie anpassen',
  'dash.settings.dataset_capture_desc': 'Zeichnet Avas Werkzeugentscheidungen, Persona-Übergaben, Speicheroperationen usw. unter ~/.ava/datasets/ auf. Standardmäßig nur lokal. Nimmt niemals deine Prompts oder Dateien auf — nur ihre Entscheidungen und Kontextstruktur.',
  'dash.settings.dataset_capture_title': 'Avas Aktionen als Trainingsdaten erfassen',
  'dash.settings.dataset_kinds': 'Datensatzarten',
  'dash.settings.dataset_kinds_desc': 'Die 10 verschiedenen Trainingsdatensätze, die Ava generiert. Alle standardmäßig aktiviert; deaktiviere jeden, zu dem du nicht beitragen möchtest.',
  'dash.settings.dataset_modes': 'Erfasste Modi',
  'dash.settings.dataset_modes_desc': 'Wähle aus, welche Denkmodi den Datensatz speisen. Schalte jeden aus, um diesen Modus privat zu halten.',
  'dash.settings.dataset_note': 'Alle Erfassung ist lokal und nur ergänzend. Nichts verlässt deinen Computer, bis du explizit in dein privates Datensatz-Repository pushest (getrennt, opt-in).',
